package com.mindtravel.reduction.model.chat

import org.junit.Assert.assertArrayEquals
import org.junit.Test

class DeepSeekTokenizerTest {
    @Test fun matchesOfficialTokenizerOnMixedLanguageTextAndSpecialTokens() {
        // Reference IDs generated by tokenizers.Tokenizer.from_file on DeepSeek's official tokenizer.json.
        val examples = mapOf(
            "" to intArrayOf(),
            "Hello!" to intArrayOf(19923, 3),
            "你好，Reduction" to intArrayOf(30594, 303, 14238, 23003),
            "API 费用 1234567890 元。" to intArrayOf(21276, 223, 9830, 223, 6895, 18009, 25744, 18, 223, 1673, 320),
            "e\u0301  👍🏽\n\n  北京大学生。" to intArrayOf(71, 17793, 223, 102527, 40965, 124, 271, 262, 6127, 18758, 320),
            "<think>abc</think> <｜User｜>" to intArrayOf(128821, 32372, 128822, 223, 128803),
            "。!abc\t\u00a0カタカナかな龍𠮷" to intArrayOf(320, 3, 32372, 200, 2162, 15961, 11767, 15961, 27071, 49534, 16519, 175, 257, 109, 118),
            "银行行长说：重复重复重复。" to intArrayOf(6487, 96953, 872, 768, 16761, 16761, 16761, 320),
            "a".repeat(128) to IntArray(16) { 89086 }
        )
        for ((text, expected) in examples) assertArrayEquals(text, expected, DeepSeekTokenizer.encode(text))
    }
}
